// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Scenario: user deposits 2 ether, unlockTime = 0 (immediately unlocked)
        // Then tries to collect 1 ether.
        // In the reference, Put works correctly; in the buggy version, the require in Put
        // (which checks acc.balance + msg.value < acc.balance) will revert because
        // 0+2 < 0 is false, so Put reverts.
        vm.deal(address(0x123), 2 ether);
        vm.prank(address(0x123));
        c.Put{value: 2 ether}(0);
        // Now attempt Collect(1 ether)
        vm.prank(address(0x123));
        bool ok;
        try c.Collect(1 ether) { ok = true; } catch { ok = false; }
        // Reference: Collect succeeds (ok == true), buggy: fails because Put (called via fallback?) fails earlier
        // Actually the bug is in Put's require, so Put fails at deposit -> test won't reach collect.
        // So we assert that the user's balance after deposit is 2 ether in reference, but in buggy Put reverts.
        // We'll directly test the Put call:
        address user = address(0x456);
        vm.deal(user, 3 ether);
        vm.prank(user);
        bool putOk;
        try c.Put{value: 3 ether}(0) { putOk = true; } catch { putOk = false; }
        assertTrue(putOk);
    }
}

