pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Setup: send a small amount first to avoid edge cases
        vm.deal(address(0x1), 1 ether);
        vm.prank(address(0x1));
        c.Put{value: 0.5 ether}(block.timestamp + 100);

        // Now try to deposit with a large amount that would overflow uint if added to existing balance
        // The reference version's require (balance + msg.value >= balance) passes for any value
        // The buggy version's require (balance + msg.value < balance) would incorrectly revert
        uint256 initialBalance = address(c).balance;
        vm.deal(address(0x2), type(uint256).max);
        vm.prank(address(0x2));
        bool ok;
        try c.Put{value: type(uint256).max - 0.5 ether}(block.timestamp + 200) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert that the call succeeded (reference version) and balance increased
        assertTrue(ok);
        assertEq(address(c).balance, initialBalance + (type(uint256).max - 0.5 ether));
    }
}

